package theoryloop

import (
	"fmt"
	"math"
)

// Planted-mechanism worlds.
//
// Each world is a synthetic panel of NFT project data whose outcome (an overall
// legitimacy score) is generated by a
// mechanism we choose. Because we wrote the mechanism, we know the true theory
// and can score whatever a theory-building loop produces against it.
//
// Variables are named after NFT platform-legitimacy constructs so the benchmark
// reads like the setting it stands in for, but no subagent sees the generating
// code, only the data. Every world contains distractors (pure noise), so there
// are many forking paths to wander down. We test specific failures:
//
//	main      a single true effect (can the loop find a simple truth?)
//	scope     an effect that exists only under a boundary condition
//	confound  a decoy correlation produced by a common cause
//	null      nothing to find (does the loop invent theory anyway?)
//	multi     a threshold effect plus a second, independent effect

// Predictors are the variables every world contains, in a fixed order.
var Predictors = []string{
	"verified",    // marketplace verification badge (binary)
	"creator_rep", // creator's prior reputation
	"community",   // size of community at launch
	"royalty",     // creator royalty rate, 0-0.10
	"wash_share",  // share of early volume that is wash trading, 0-1
	"bear_launch", // launched in a bear market (binary)
	"roadmap_len", // distractor
	"art_entropy", // distractor
	"mint_hour",   // distractor
	"supply_log",  // distractor
}

var binary = map[string]bool{"verified": true, "bear_launch": true}

// Outcome is the dependent variable in every world.
const Outcome = "legitimacy"

// WorldNames lists the worlds in benchmark order.
var WorldNames = []string{"main", "scope", "confound", "null", "multi"}

// Slot is the set of propositions that state one planted mechanism equally
// well. For a pure interaction, "X matters when Z=1" and "Z matters when X=1"
// fit the data identically: which variable is focal is a framing choice the
// data cannot make, so either counts as recovering the mechanism.
type Slot []Proposition

// World is a dataset plus the mechanisms that generated it.
type World struct {
	Name        string
	Description string
	Truth       []Slot
	Data        Data
}

func isPredictor(name string) bool {
	for _, p := range Predictors {
		if p == name {
			return true
		}
	}
	return false
}

// MakeWorld generates world name with n projects. The same name, seed and n
// always produce the same data.
func MakeWorld(name string, seed uint64, n int) (World, error) {
	r := newRNG(seed, 1)
	cols := make(map[string][]float64, len(Predictors)+1)
	fill := func(col string, draw func() float64) {
		c := make([]float64, n)
		for i := range c {
			c[i] = draw()
		}
		cols[col] = c
	}
	fill("verified", func() float64 { return r.bernoulli(0.4) })
	fill("creator_rep", r.normal)
	fill("community", r.normal)
	fill("royalty", func() float64 { return 0.10 * r.uniform() })
	fill("wash_share", func() float64 { return r.beta(2, 8) })
	fill("bear_launch", func() float64 { return r.bernoulli(0.5) })
	fill("roadmap_len", r.normal)
	fill("art_entropy", r.normal)
	fill("mint_hour", func() float64 { return float64(r.intn(24)) })
	fill("supply_log", func() float64 { return 8 + r.normal() })
	e := make([]float64, n)
	for i := range e {
		e[i] = r.normal()
	}

	v, bear, comm := cols["verified"], cols["bear_launch"], cols["community"]
	wash, rep := cols["wash_share"], cols["creator_rep"]
	y := make([]float64, n)
	w := World{Name: name}

	switch name {
	case "main":
		for i := range y {
			y[i] = 0.30*v[i] + e[i]
		}
		w.Truth = []Slot{{P("verified", 1)}}
		w.Description = "Verification raises legitimacy everywhere."
	case "scope":
		for i := range y {
			y[i] = 0.45*v[i]*bear[i] + e[i]
		}
		w.Truth = []Slot{{PWhen("verified", 1, "bear_launch", 1), PWhen("bear_launch", 1, "verified", 1)}}
		w.Description = "Verification matters only for projects launched in a bear market."
	case "confound":
		// Community size drives BOTH verification and legitimacy; verification does nothing.
		for i := range v {
			v[i] = r.bernoulli(1 / (1 + math.Exp(-(1.6*comm[i] - 0.4))))
		}
		for i := range y {
			y[i] = 0.40*comm[i] + e[i]
		}
		w.Truth = []Slot{{P("community", 1)}}
		w.Description = "Community drives both verification and legitimacy; verification is a decoy."
	case "null":
		copy(y, e)
		w.Description = "No mechanism. Any proposition is a false discovery."
	case "multi":
		for i := range y {
			heavy := 0.0
			if wash[i] > 0.30 {
				heavy = 1
			}
			y[i] = -0.55*heavy + 0.20*rep[i] + e[i]
		}
		w.Truth = []Slot{{P("wash_share", -1)}, {P("creator_rep", 1)}}
		w.Description = "Heavy wash trading destroys legitimacy (threshold); creator reputation helps."
	default:
		return World{}, fmt.Errorf("unknown world %q", name)
	}
	cols[Outcome] = y
	w.Data = Data{N: n, Cols: cols}
	return w, nil
}
